function json(data: unknown, status = 200) {
  return new Response(JSON.stringify(data, null, 2), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });
}

function text(value: unknown, max = 160) { return typeof value === "string" ? value.trim().slice(0, max) : undefined; }
function nullableNumber(value: unknown, min: number, max: number) {
  if (value === null || value === "") return null;
  const normalized = typeof value === "string"
    ? (value.includes(",") ? value.trim().replace(/\./g, "").replace(",", ".") : value.trim())
    : value;
  const n = Number(normalized);
  return Number.isFinite(n) && n >= min && n <= max ? n : undefined;
}
function validTemplate(value: unknown): ContentTemplate {
  return ["offer", "natural", "storytelling", "no_price"].includes(String(value)) ? String(value) as ContentTemplate : "offer";
}
function nextSlot(expression: string | null, timezone: string, from = new Date()) {
  if (!expression) return null;
  const start = new Date(from.getTime() + 60_000); start.setUTCSeconds(0, 0);
  for (let i = 0; i < 10_080; i += 1) {
    const candidate = new Date(start.getTime() + i * 60_000);
    if (cronMatches(expression, candidate, timezone)) return candidate.toISOString();
  }
  return null;
}
function intervalValue(settings: JsonObject) {
  const value = Number(settings?.intervalMinutes);
  return Number.isInteger(value) && value >= 5 && value <= 1440 && value % 5 === 0 ? value : null;
}
function validClock(value: unknown, fallback: string) {
  const v = typeof value === "string" ? value : fallback;
  return /^([01]\d|2[0-3]):[0-5]\d$/.test(v) ? v : fallback;
}
function clockToMinutes(value: string) { const [h,m]=value.split(":").map(Number); return h*60+m; }
function localClockMinutes(date: Date, timezone: string) {
  const parts=Object.fromEntries(new Intl.DateTimeFormat("en-US",{timeZone:timezone,hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(date).map(p=>[p.type,p.value]));
  return Number(parts.hour)*60+Number(parts.minute);
}
function inRuleWindow(date: Date, timezone: string, settings: JsonObject) {
  const start=clockToMinutes(validClock(settings?.windowStart,"09:00"));
  const end=clockToMinutes(validClock(settings?.windowEnd,"22:00"));
  const current=localClockMinutes(date,timezone);
  return start<=end ? current>=start&&current<=end : current>=start||current<=end;
}
function nextRuleSlot(rule: AutomationRuleRow, lastRunAt: string | null, from = new Date()) {
  const interval=intervalValue(rule.settings||{});
  const timezone=rule.timezone||"America/Sao_Paulo";
  if (!interval) return nextSlot(rule.schedule_cron,timezone,from);
  const earliest=lastRunAt ? Math.max(from.getTime()+60_000,new Date(lastRunAt).getTime()+interval*60_000) : from.getTime()+60_000;
  let candidate=new Date(earliest);
  candidate.setUTCSeconds(0,0);
  const remainder=candidate.getUTCMinutes()%5;
  if(remainder!==0) candidate=new Date(candidate.getTime()+(5-remainder)*60_000);
  for(let i=0;i<2_016;i+=1){
    if(inRuleWindow(candidate,timezone,rule.settings||{})) return candidate.toISOString();
    candidate=new Date(candidate.getTime()+5*60_000);
  }
  return null;
}
function safeConfig(env: Env) {
  return { shopee: Boolean(env.SHOPEE_APP_ID && env.SHOPEE_SECRET), telegram: Boolean(env.TELEGRAM_BOT_TOKEN && env.TELEGRAM_CHAT_ID), supabase: Boolean(env.SUPABASE_URL && (env.SUPABASE_SECRET_KEY || env.SUPABASE_SERVICE_ROLE_KEY)), protectedEndpoints: Boolean(env.AUTOMATION_SECRET) };
}

function rulePatch(input: AdminRuleInput, creating = false, currentSettings: JsonObject = {}) {
  const patch: JsonObject = {};
  if (input.name !== undefined) { const v = text(input.name, 120); if (!v) throw new Error("Nome obrigatório."); patch.name = v; } else if (creating) throw new Error("Nome obrigatório.");
  // A busca comercial é ampla e baseada nos filtros/estratégias.
  // Mantemos a coluna keyword vazia apenas por compatibilidade com o schema atual.
  patch.keyword = "";
  if (input.enabled !== undefined) patch.enabled = Boolean(input.enabled);
  if (input.dry_run !== undefined) patch.dry_run = Boolean(input.dry_run);
  for (const [key, min, max] of [["min_commission",0,100],["min_discount",0,100],["max_price",0,1_000_000]] as const) {
    if (input[key] !== undefined) { const v = nullableNumber(input[key], min, max); if (v === undefined) throw new Error(`${key} inválido.`); patch[key] = v; }
  }
  if (input.quantity !== undefined) { const v=Number(input.quantity); if(!Number.isInteger(v)||v<1||v>100) throw new Error("Quantidade inválida."); patch.quantity=v; }
  if (input.avoid_repeat_days !== undefined) { const v=Number(input.avoid_repeat_days); if(!Number.isInteger(v)||v<0||v>365) throw new Error("Dias sem repetir inválido."); patch.avoid_repeat_days=v; }
  if (input.sort !== undefined) { const v=input.sort===null||input.sort===""?null:String(input.sort); if(v!==null&&!['commission','price','sales','discount'].includes(v)) throw new Error("Ordenação inválida."); patch.sort=v; }
  if (input.schedule_cron !== undefined) { const v=input.schedule_cron===null?null:text(input.schedule_cron,100); if(v&&v.split(/\s+/).length!==5) throw new Error("Cron deve ter 5 campos."); patch.schedule_cron=v||null; } else if (creating) patch.schedule_cron="0 9-22 * * *";
  if (input.timezone !== undefined) { const v=text(input.timezone,80); if(!v) throw new Error("Timezone inválido."); try{new Intl.DateTimeFormat("pt-BR",{timeZone:v}).format(new Date());}catch{throw new Error("Timezone inválido.");} patch.timezone=v; } else if(creating) patch.timezone="America/Sao_Paulo";
  if (input.settings !== undefined) {
    if (!input.settings || typeof input.settings !== "object" || Array.isArray(input.settings)) throw new Error("Settings inválido.");
    patch.settings = { ...currentSettings, ...(input.settings as JsonObject), searchScope: "all" };
    const nextSettings = patch.settings as JsonObject;
    if (Boolean(nextSettings.flexCommissionEnabled)) {
      const target = Number(patch.min_commission);
      if (!Number.isFinite(target) || target <= 0) {
        throw new Error("Informe uma comissão desejada maior que 0% antes de ativar a flexibilização.");
      }
      const step = Number(nextSettings.flexCommissionStep || 5);
      if (![5, 10].includes(step)) throw new Error("A redução da comissão deve ser de 5 ou 10 pontos percentuais.");
      const rawFloor = Number(nextSettings.flexCommissionFloor);
      const suggestedFloor = Math.max(1, Math.round(target * 0.6 * 10) / 10);
      const floor = Number.isFinite(rawFloor) && rawFloor > 0 ? rawFloor : suggestedFloor;
      if (floor > target) throw new Error("A comissão mínima absoluta não pode ser maior que a comissão desejada.");
      nextSettings.flexCommissionStep = step;
      nextSettings.flexCommissionFloor = Math.round(floor * 10) / 10;
    }
  }
  if (creating) {
    patch.id=crypto.randomUUID(); patch.networks=["shopee"]; patch.channels=["telegram"];
    if(patch.enabled===undefined) patch.enabled=false; if(patch.dry_run===undefined) patch.dry_run=true; if(patch.quantity===undefined) patch.quantity=1; if(patch.avoid_repeat_days===undefined) patch.avoid_repeat_days=7;
    patch.settings={ purpose:"admin_ui", priority:100, maxAttempts:3, contentTemplate:"offer", intervalMinutes:60, windowStart:"09:00", windowEnd:"22:00", ...(patch.settings as JsonObject || {}), searchScope:"all" };
  }
  return patch;
}

async function dashboard(env: Env) {
  const db=new SupabaseRest(env); const since=new Date(Date.now()-86_400_000).toISOString(); const now=new Date();
  const [rules,runs,queue,published,logs,p24,open,failed]=await Promise.all([
    db.select<AutomationRuleRow>("automation_rules",new URLSearchParams({select:"*",order:"created_at.desc"})),
    db.select<JsonObject>("automation_runs",new URLSearchParams({select:"*",order:"started_at.desc",limit:"60"})),
    db.select<JsonObject>("publication_queue",new URLSearchParams({select:"*",order:"created_at.desc",limit:"200"})),
    db.select<JsonObject>("published_offers",new URLSearchParams({select:"*",order:"published_at.desc",limit:"120"})),
    db.select<JsonObject>("publication_logs",new URLSearchParams({select:"*",order:"created_at.desc",limit:"160"})),
    db.select<{id:number}>("published_offers",new URLSearchParams({select:"id",published_at:`gte.${since}`})),
    db.select<{id:string}>("publication_queue",new URLSearchParams({select:"id",status:"in.(pending,processing,retry)"})),
    db.select<{id:string}>("publication_queue",new URLSearchParams({select:"id",status:"eq.failed",updated_at:`gte.${since}`})),
  ]);
  const nextRuns=Object.fromEntries(rules.map(r=>{
    const nextQueued=(queue as any[])
      .filter(q=>q.rule_id===r.id&&["pending","processing","retry"].includes(String(q.status))&&q.scheduled_for)
      .sort((a,b)=>new Date(a.scheduled_for).getTime()-new Date(b.scheduled_for).getTime())[0];
    if(nextQueued) return [r.id,String(nextQueued.scheduled_for)];
    const last=runs.find((run:any)=>run.rule_id===r.id) as any;
    return [r.id,r.enabled?nextRuleSlot(r,last?.started_at?String(last.started_at):null,now):null];
  }));
  return {ok:true,generatedAt:now.toISOString(),config:safeConfig(env),metrics:{activeRules:rules.filter(r=>r.enabled).length,totalRules:rules.length,published24h:p24.length,queueOpen:open.length,failed24h:failed.length,successRate:p24.length+failed.length?Math.round(p24.length/(p24.length+failed.length)*1000)/10:100},nextRuns,rules,runs,queue,published,logs};
}

async function telegramInfo(env: Env) {
  if(!env.TELEGRAM_BOT_TOKEN||!env.TELEGRAM_CHAT_ID) return {configured:false,topics:[]};
  const token=env.TELEGRAM_BOT_TOKEN; const chatId=env.TELEGRAM_CHAT_ID;
  async function call(method:string,body:JsonObject={}) { const r=await fetch(`https://api.telegram.org/bot${token}/${method}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body),signal:AbortSignal.timeout(10_000)}); const p=await r.json() as any; if(!r.ok||!p?.ok) throw new Error(p?.description||`Telegram HTTP ${r.status}`); return p.result; }
  const db=new SupabaseRest(env);
  const [me,chat,rules,storedTopics]=await Promise.all([
    call("getMe"),
    call("getChat",{chat_id:chatId}),
    db.select<AutomationRuleRow>("automation_rules",new URLSearchParams({select:"id,name,settings",order:"created_at.desc"})),
    db.select<TelegramTopicRow>("telegram_topics",new URLSearchParams({select:"*",chat_id:eq(chatId),enabled:"eq.true",order:"name.asc"})),
  ]);
  const topicMap=new Map<number,{name:string,stored:boolean}>();
  for(const topic of storedTopics){
    const id=Number(topic.thread_id);
    if(Number.isInteger(id)&&id>0) topicMap.set(id,{name:topic.name||`Tópico ${id}`,stored:true});
  }
  for(const rule of rules){
    const id=Number(rule.settings?.telegramThreadId);
    if(Number.isInteger(id)&&id>0&&!topicMap.has(id)){
      const name=typeof rule.settings?.telegramTopicName==="string"&&String(rule.settings.telegramTopicName).trim()?String(rule.settings.telegramTopicName).trim():`Tópico ${id}`;
      topicMap.set(id,{name,stored:false});
    }
  }
  const topics=Array.from(topicMap.entries()).map(([id,value])=>({id,name:value.name,stored:value.stored})).sort((a,b)=>a.name.localeCompare(b.name,"pt-BR"));
  return {configured:true,botUsername:me?.username||null,botName:me?.first_name||null,chatTitle:chat?.title||chat?.username||"Grupo Telegram",isForum:Boolean(chat?.is_forum),chatType:chat?.type||null,topics};
}

function buildPreviewSuggestions(
  diagnostics: { [key: string]: number },
  filters: { minCommission?: number | null; minDiscount?: number | null; maxPrice?: number | null },
) {
  if (!diagnostics.scanned) return ["A Shopee não retornou ofertas nas estratégias consultadas. Tente novamente em alguns instantes ou revise os filtros."];

  const candidates = [
    { count: diagnostics.rejectedRelevance || 0, text: "Alguns anúncios foram descartados por relevância ou qualidade do produto." },
    { count: diagnostics.belowCommission || 0, text: filters.minCommission != null ? `Reduza a comissão mínima de ${filters.minCommission}% ou deixe esse filtro vazio.` : "Revise a comissão mínima." },
    { count: diagnostics.belowDiscount || 0, text: filters.minDiscount != null ? `Reduza o desconto mínimo de ${filters.minDiscount}% ou deixe esse filtro vazio.` : "Revise o desconto mínimo." },
    { count: diagnostics.aboveMaxPrice || 0, text: filters.maxPrice != null ? `Aumente o preço máximo de R$ ${filters.maxPrice.toFixed(2).replace(".", ",")} ou deixe esse filtro vazio.` : "Revise o preço máximo." },
    { count: diagnostics.equivalentDuplicates || 0, text: "Há anúncios equivalentes entre os resultados; amplie a busca para encontrar produtos realmente diferentes." },
    { count: diagnostics.invalidMetrics || 0, text: "Alguns anúncios vieram com métricas inválidas da rede e foram descartados por segurança." },
  ].filter((item) => item.count > 0).sort((a, b) => b.count - a.count);

  return candidates.slice(0, 3).map((item) => item.text);
}

async function preview(request: Request, env: Env) {
  const body=await request.json().catch(()=>({})) as JsonObject;
  const settings=(body.settings&&typeof body.settings==="object"&&!Array.isArray(body.settings)?body.settings:{}) as JsonObject;
  const minCommission=nullableNumber(body.minCommission??body.min_commission,0,100)??undefined;
  const minDiscount=nullableNumber(body.minDiscount??body.min_discount,0,100)??undefined;
  const maxPrice=nullableNumber(body.maxPrice??body.max_price,0,1_000_000)??undefined;
  const quantityRaw=Number(body.quantity||1);
  const quantity=Number.isInteger(quantityRaw)?Math.min(Math.max(quantityRaw,1),20):1;
  const requestedSort=["commission","price","sales","discount"].includes(String(body.sort))?String(body.sort) as AutomationRuleRow["sort"]:null;
  const timezone=text(body.timezone,80)||"America/Sao_Paulo";
  const previewRule:AutomationRuleRow={id:"preview",name:"Prévia",enabled:false,networks:["shopee"],channels:["telegram"],keyword:"",category:null,min_commission:minCommission??null,min_discount:minDiscount??null,max_price:maxPrice??null,quantity,sort:requestedSort,avoid_repeat_days:0,schedule_cron:null,timezone,dry_run:true,settings:{...settings,searchScope:"all"}};
  const result=await searchOffersForRule(new SupabaseRest(env),env,previewRule,quantity,undefined,new Date());
  const template=validTemplate(settings.contentTemplate);
  const thread=Number(settings.telegramThreadId);
  const messageThreadId=Number.isInteger(thread)&&thread>0?thread:undefined;
  const flexEnabled=Boolean(settings.flexCommissionEnabled)&&Number(result.commissionTarget)>0;
  const attempts=(result.commissionAttemptStats||[]).map((item)=>({threshold:item.threshold,eligible:item.eligible}));
  const diagnostics={scanned:result.scanned,rejectedRelevance:0,invalidMetrics:0,belowCommission:0,belowDiscount:0,aboveMaxPrice:0,equivalentDuplicates:0,excludedRecent:result.excluded,eligible:result.selected.length,zeroSalesAccepted:result.selected.filter((offer)=>Number(offer.sourceMetadata?.sales)===0).length,zeroRatingAccepted:result.selected.filter((offer)=>Number(offer.sourceMetadata?.rating)===0).length};
  const suggestions:string[]=[];
  if(result.selected.length===0){
    if(flexEnabled){suggestions.push(`A busca real percorreu a meta de ${result.commissionTarget}% até o piso de ${Number(settings.flexCommissionFloor)||result.commissionTarget}% sem encontrar uma oferta que também cumpra desconto, preço e fonte selecionados.`);if(minDiscount!=null)suggestions.push(`O desconto mínimo de ${minDiscount}% continua obrigatório em todas as faixas de comissão.`);}
    else{if(minCommission!=null)suggestions.push(`A comissão está rígida em ${minCommission}%. Ative a flexibilização para permitir faixas menores.`);if(minDiscount!=null)suggestions.push(`Revise o desconto mínimo de ${minDiscount}% se quiser ampliar a busca.`);}
  }
  return json({dryRun:true,selected:result.selected.length,scanned:result.scanned,pages:result.pages,diagnostics,filters:{minCommission:minCommission??null,minDiscount:minDiscount??null,maxPrice:maxPrice??null},suggestions,commissionFlex:{enabled:flexEnabled,target:result.commissionTarget,floor:Number(settings.flexCommissionFloor)||result.commissionTarget,step:Number(settings.flexCommissionStep)||5,resolved:result.commissionResolved,attempts},selectionEngine:"automation",sourceMode:result.sourceMode,sourceNiche:result.sourceNiche,strategy:{scope:result.sourceMode,requests:result.pages,queries:result.sourceNiche?[result.sourceNiche]:["Todos os produtos"],sourceSorts:[requestedSort||"relevance"]},publications:result.selected.map((offer)=>({offer,content:generateContent(offer,"telegram",{template,messageThreadId})}))});
}


function planDateKey(date: Date, timezone: string) {
  const parts=Object.fromEntries(new Intl.DateTimeFormat("en-CA",{timeZone:timezone,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(date).map((part)=>[part.type,part.value]));
  return `${parts.year}-${parts.month}-${parts.day}`;
}
function validDateKey(value: unknown) { const v=typeof value==="string"?value:""; return /^\d{4}-\d{2}-\d{2}$/.test(v)?v:""; }
function shiftDateKey(key: string, days: number) { const d=new Date(`${key}T12:00:00Z`); d.setUTCDate(d.getUTCDate()+days); return d.toISOString().slice(0,10); }
function dateKeyWeekday(key: string) { return new Date(`${key}T12:00:00Z`).getUTCDay(); }
function planWeekdays(settings: JsonObject) {
  const raw=Array.isArray(settings.activeWeekdays)?settings.activeWeekdays.map(Number).filter((v)=>Number.isInteger(v)&&v>=0&&v<=6):[];
  return raw.length?Array.from(new Set(raw)):[0,1,2,3,4,5,6];
}
function firstPlanDate(settings: JsonObject, timezone: string) {
  const today=planDateKey(new Date(),timezone); const configured=validDateKey(settings.activeStartDate); let key=configured&&configured>today?configured:today;
  const end=validDateKey(settings.activeEndDate); const allowed=planWeekdays(settings);
  for(let guard=0;guard<3700;guard+=1){ if(end&&key>end)return null; if(allowed.includes(dateKeyWeekday(key)))return key; key=shiftDateKey(key,1); }
  return null;
}
function nextPlanDateAfter(settings: JsonObject, afterDate: string) {
  const end=validDateKey(settings.activeEndDate); const allowed=planWeekdays(settings); let key=shiftDateKey(afterDate,1);
  for(let guard=0;guard<3700;guard+=1){ if(end&&key>end)return null; if(allowed.includes(dateKeyWeekday(key)))return key; key=shiftDateKey(key,1); }
  return null;
}
function zonedPlanDate(dateKey: string, totalMinutes: number, timezone: string) {
  const dayOffset=Math.floor(totalMinutes/1440); const minute=((totalMinutes%1440)+1440)%1440; const shifted=shiftDateKey(dateKey,dayOffset);
  const [year,month,day]=shifted.split("-").map(Number); const hour=Math.floor(minute/60); const min=minute%60; const desired=Date.UTC(year,month-1,day,hour,min,0,0);
  let guess=new Date(desired);
  for(let pass=0;pass<3;pass+=1){
    const parts=Object.fromEntries(new Intl.DateTimeFormat("en-CA",{timeZone:timezone,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(guess).map((part)=>[part.type,part.value]));
    const observed=Date.UTC(Number(parts.year),Number(parts.month)-1,Number(parts.day),Number(parts.hour),Number(parts.minute),0,0);
    const delta=desired-observed; if(!delta)break; guess=new Date(guess.getTime()+delta);
  }
  return guess;
}
function planSlots(dateKey: string, settings: JsonObject, timezone: string) {
  const start=clockToMinutes(validClock(settings.windowStart,"09:00")); const end=clockToMinutes(validClock(settings.windowEnd,"22:00")); const interval=intervalValue(settings)||60;
  const span=start<=end?end-start:(1440-start)+end; const count=Math.floor(span/interval)+1; const slots=[] as Array<{index:number;time:string;date:Date;nicheId:string|null}>;
  for(let index=0;index<count;index+=1){ const total=start+index*interval; const minute=((total%1440)+1440)%1440; const hh=String(Math.floor(minute/60)).padStart(2,"0"),mm=String(minute%60).padStart(2,"0"); const date=zonedPlanDate(dateKey,total,timezone); slots.push({index,time:`${hh}:${mm}`,date,nicheId:null}); }
  return slots;
}
function countPlanDays(settings: JsonObject, firstDate: string) {
  const end=validDateKey(settings.activeEndDate); if(!end)return null; const allowed=planWeekdays(settings); let key=firstDate,count=0;
  for(let guard=0;guard<3700&&key<=end;guard+=1){ if(allowed.includes(dateKeyWeekday(key)))count+=1; key=shiftDateKey(key,1); }
  return count;
}
async function recentPlanOffers(db: SupabaseRest, days: number) {
  if(days<=0)return [] as Offer[]; const cutoff=new Date(Date.now()-days*86_400_000).toISOString();
  const rows=await db.select<{offer_snapshot:Offer|null}>("publication_queue",new URLSearchParams({select:"offer_snapshot",status:"eq.published",published_at:`gte.${cutoff}`,order:"published_at.desc",limit:"500"}));
  return rows.map((row)=>row.offer_snapshot).filter((offer):offer is Offer=>Boolean(offer));
}
async function firstDayPlanPreview(request: Request, env: Env) {
  const body=await request.json().catch(()=>({})) as JsonObject; const settings=(body.settings&&typeof body.settings==="object"&&!Array.isArray(body.settings)?body.settings:{}) as JsonObject;
  const minCommission=nullableNumber(body.minCommission??body.min_commission,0,100)??undefined; const minDiscount=nullableNumber(body.minDiscount??body.min_discount,0,100)??undefined; const maxPrice=nullableNumber(body.maxPrice??body.max_price,0,1_000_000)??undefined;
  const requestedSort=["commission","price","sales","discount"].includes(String(body.sort))?String(body.sort) as AutomationRuleRow["sort"]:null; const timezone=text(body.timezone,80)||"America/Sao_Paulo";
  const repeatRaw=nullableNumber(body.avoidRepeatDays??body.avoid_repeat_days,0,365); const avoidRepeatDays=repeatRaw==null?0:Math.round(repeatRaw);
  const now=new Date(); const todayKey=planDateKey(now,timezone); const initialDateKey=firstPlanDate(settings,timezone); if(!initialDateKey)return json({error:"Nenhum dia ativo disponível dentro do período selecionado."},422);
  let dateKey=initialDateKey; let fullDaySlots=planSlots(dateKey,settings,timezone); let allSlots=dateKey===todayKey?fullDaySlots.filter((slot)=>slot.date.getTime()>=now.getTime()):fullDaySlots;
  let skippedPastSlots=Math.max(0,fullDaySlots.length-allSlots.length); let rolledToNextDay=false;
  if(dateKey===todayKey&&allSlots.length===0){
    const nextDate=nextPlanDateAfter(settings,dateKey);
    if(!nextDate)return json({error:"A janela de publicação de hoje já terminou e não há outro dia ativo disponível no período selecionado."},422);
    dateKey=nextDate; fullDaySlots=planSlots(dateKey,settings,timezone); allSlots=fullDaySlots; rolledToNextDay=true;
  }
  const adjustedForCurrentTime=initialDateKey===todayKey&&skippedPastSlots>0&&!rolledToNextDay;
  const currentLocalTime=new Intl.DateTimeFormat("pt-BR",{timeZone:timezone,hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).format(now);
  const MAX_PREVIEW_SLOTS=180; const slots=allSlots.slice(0,MAX_PREVIEW_SLOTS); const truncated=allSlots.length>slots.length;
  const rule:AutomationRuleRow={id:"first-day-plan",name:"Agenda prevista",enabled:false,networks:["shopee"],channels:["telegram"],keyword:"",category:null,min_commission:minCommission??null,min_discount:minDiscount??null,max_price:maxPrice??null,quantity:1,sort:requestedSort,avoid_repeat_days:avoidRepeatDays,schedule_cron:null,timezone,dry_run:true,settings:{...settings,searchScope:"all"}};
  const db=new SupabaseRest(env); const recent=await recentPlanOffers(db,avoidRepeatDays); const planned:Offer[]=[];
  const excluded=(offer:Offer)=>recent.some((old)=>productsLookEquivalent(old,offer))||planned.some((old)=>productsLookEquivalent(old,offer));
  type Assignment={offer:Offer;commissionResolved:number|null;sourceNiche:string|null;scanned:number;pages:number}; const assignments=new Map<number,Assignment>(); let scanned=0,pages=0;
  const MAX_PROGRESSIVE_ROUNDS=6; const PAGE_STRIDE=2; let progressiveRounds=0; let progressiveSearchExhausted=false;
  const fill=async(group:typeof slots,slotDate:Date)=>{
    if(!group.length)return;
    let remaining=group.filter((slot)=>!assignments.has(slot.index));
    let stalledRounds=0;
    for(let round=0;round<MAX_PROGRESSIVE_ROUNDS&&remaining.length;round+=1){
      const before=assignments.size;
      const pageStart=1+round*PAGE_STRIDE;
      const result=await searchOffersForRule(db,env,rule,remaining.length,excluded,slotDate,{pageStart,maxPages:2,maxRequests:8});
      scanned+=result.scanned; pages+=result.pages; progressiveRounds=Math.max(progressiveRounds,round+1);
      result.selected.forEach((offer,index)=>{ const target=remaining[index]; if(!target)return; planned.push(offer); assignments.set(target.index,{offer,commissionResolved:result.commissionResolved,sourceNiche:result.sourceNiche,scanned:result.scanned,pages:result.pages}); });
      remaining=group.filter((slot)=>!assignments.has(slot.index));
      if(assignments.size===before) stalledRounds+=1; else stalledRounds=0;
      if(stalledRounds>=2){ progressiveSearchExhausted=true; break; }
    }
    if(remaining.length&&progressiveRounds>=MAX_PROGRESSIVE_ROUNDS) progressiveSearchExhausted=true;
  };
  const mode=sourceMode(settings);
  if(mode==="mix"){
    const groups=new Map<string,typeof slots>();
    for(const slot of slots){ const niche=chooseMixNiche(settings,slot.date,timezone)||""; slot.nicheId=niche||null; const group=groups.get(niche)||[]; group.push(slot); groups.set(niche,group); }
    for(const group of groups.values())await fill(group,group[0].date);
  }else await fill(slots,slots[0]?.date||new Date());
  const defaultNiche=mode==="niche"?nicheLabel(settings.niche):mode==="list"?String(settings.listName||"Lista inteligente"):mode==="all"?"Todos os nichos":null;
  const output=slots.map((slot)=>{ const found=assignments.get(slot.index); const requestedNiche=slot.nicheId?nicheLabel(slot.nicheId):defaultNiche; return {index:slot.index,time:slot.time,scheduledFor:slot.date.toISOString(),requestedNiche,status:found?"filled":"missing",commissionResolved:found?.commissionResolved??null,sourceNiche:found?.sourceNiche??null,offer:found?.offer??null}; });
  const filled=output.filter((slot)=>slot.status==="filled").length; const activeDays=countPlanDays(settings,dateKey); const futureDays=activeDays==null?null:Math.max(0,activeDays-1);
  return json({dryRun:true,firstDay:dateKey,totalSlots:allSlots.length,fullDaySlots:fullDaySlots.length,previewedSlots:slots.length,filled,missing:Math.max(0,allSlots.length-filled),coverage:allSlots.length?Math.round((filled/allSlots.length)*1000)/10:0,truncated,scanned,pages,progressiveSearch:true,progressiveRounds,progressiveSearchExhausted,continuous:activeDays==null,activeDays,futureDays,revalidateBeforePublish:true,adjustedForCurrentTime,rolledToNextDay,skippedPastSlots,currentLocalTime,firstScheduledTime:output[0]?.time||null,slots:output,message:activeDays==null||(futureDays??0)>0?"Somente o primeiro dia é planejado agora. Nos próximos dias, novos produtos serão buscados automaticamente quando cada novo ciclo diário começar e serão revalidados perto de cada horário.":"A agenda abaixo cobre o único dia ativo selecionado."});
}

export async function handleAdminApi(request: Request, env: Env) {
  const url=new URL(request.url); const path=url.pathname; const db=new SupabaseRest(env);
  const catalogResponse=await handleCatalogAdminApi(request,env);
  if(catalogResponse) return catalogResponse;
  if(request.method==="GET"&&path==="/api/admin/dashboard") return json(await dashboard(env));
  if(request.method==="GET"&&path==="/api/admin/telegram") { try{return json(await telegramInfo(env));}catch(e){return json({configured:true,error:e instanceof Error?e.message:"Falha Telegram"},502);} }
  if(request.method==="POST"&&path==="/api/admin/telegram/topics") {
    const body=await request.json().catch(()=>({})) as JsonObject;
    const threadId=Number(body.threadId);
    if(!Number.isInteger(threadId)||threadId<=0) return json({error:"Informe um ID de tópico válido."},400);
    const name=text(body.name,120)||`Tópico ${threadId}`;
    const chatId=required(env.TELEGRAM_CHAT_ID,"TELEGRAM_CHAT_ID");
    const rows=await db.insert<TelegramTopicRow>("telegram_topics?on_conflict=chat_id,thread_id",{
      chat_id:chatId,thread_id:threadId,name,enabled:true,updated_at:new Date().toISOString()
    },"resolution=merge-duplicates,return=representation");
    return json({ok:true,topic:{id:Number(rows[0]?.thread_id||threadId),name:rows[0]?.name||name,stored:true}},201);
  }
  if(request.method==="POST"&&path==="/api/admin/preview") return preview(request,env);
  if(request.method==="POST"&&path==="/api/admin/plan-preview") return firstDayPlanPreview(request,env);
  if(request.method==="POST"&&path==="/api/admin/telegram/test") {
    const body=await request.json().catch(()=>({})) as JsonObject; if(body.confirm!=="SEND_TEST") return json({error:"CONFIRMATION_REQUIRED"},409);
    const thread=Number(body.messageThreadId); const publisher=createTelegramPublisher({token:required(env.TELEGRAM_BOT_TOKEN,"TELEGRAM_BOT_TOKEN"),chatId:required(env.TELEGRAM_CHAT_ID,"TELEGRAM_CHAT_ID")});
    const result=await publisher.publish({channel:"telegram",title:"Teste",body:"✅ Teste técnico da automação",cta:"Cloudflare Worker → Telegram funcionando.",affiliateUrl:"https://shopee.com.br",messageThreadId:Number.isInteger(thread)&&thread>0?thread:undefined});
    return json({ok:true,externalId:result.externalId});
  }
  if(request.method==="POST"&&path==="/api/admin/rules") { const body=await request.json().catch(()=>({})) as AdminRuleInput; const rows=await db.insert<AutomationRuleRow>("automation_rules",rulePatch(body,true)); return json({ok:true,rule:rows[0]},201); }
  const ruleMatch=path.match(/^\/api\/admin\/rules\/([0-9a-f-]{36})$/i);
  if(ruleMatch&&request.method==="PATCH") { const existing=await db.select<AutomationRuleRow>("automation_rules",new URLSearchParams({select:"*",id:eq(ruleMatch[1]),limit:"1"})); if(!existing.length)return json({error:"Automação não encontrada."},404); const body=await request.json().catch(()=>({})) as AdminRuleInput; const patch=rulePatch(body,false,existing[0].settings||{}); const rows=await db.update<AutomationRuleRow>("automation_rules",new URLSearchParams({id:eq(ruleMatch[1])}),patch); return json({ok:true,rule:rows[0]}); }
  const runMatch=path.match(/^\/api\/admin\/rules\/([0-9a-f-]{36})\/run$/i);
  if(runMatch&&request.method==="POST") { const rows=await db.select<AutomationRuleRow>("automation_rules",new URLSearchParams({select:"*",id:eq(runMatch[1]),limit:"1"})); if(!rows.length)return json({error:"Automação não encontrada."},404); const body=await request.json().catch(()=>({})) as JsonObject; if(!rows[0].dry_run&&body.confirm!=="RUN_NOW") return json({error:"CONFIRMATION_REQUIRED",message:"Confirme a publicação real."},409); return json({ok:true,...await runRuleNow(env,runMatch[1])}); }
  const queueMatch=path.match(/^\/api\/admin\/queue\/([0-9a-f-]{36})\/(retry|cancel)$/i);
  if(queueMatch&&request.method==="POST") {
    const rows=await db.select<JsonObject>("publication_queue",new URLSearchParams({select:"*",id:eq(queueMatch[1]),limit:"1"})); if(!rows.length)return json({error:"Item não encontrado."},404); const q=rows[0] as any; const action=queueMatch[2];
    if(action==="retry") { if(!["failed","retry"].includes(String(q.status))) return json({error:"Este item não pode ser reenviado."},409); await db.update("publication_queue",new URLSearchParams({id:eq(queueMatch[1])}),{status:"pending",attempts:0,available_at:new Date().toISOString(),scheduled_for:new Date().toISOString(),locked_at:null,locked_by:null,last_error:null}); await db.insert("publication_logs",{queue_id:q.id,run_id:q.run_id,rule_id:q.rule_id,event:"manual_retry",status:"pending",message:"Retry solicitado pelo painel"},"return=minimal"); const worker=await workerTick(env); return json({ok:true,worker}); }
    if(!["pending","retry","failed"].includes(String(q.status))) return json({error:"Este item não pode ser cancelado."},409); await db.update("publication_queue",new URLSearchParams({id:eq(queueMatch[1])}),{status:"cancelled",locked_at:null,locked_by:null}); await db.insert("publication_logs",{queue_id:q.id,run_id:q.run_id,rule_id:q.rule_id,event:"manual_cancel",status:"cancelled",message:"Cancelado pelo painel"},"return=minimal"); return json({ok:true});
  }
  return json({error:"NOT_FOUND"},404);
}

