  function enrichRequest(input,init){var url=typeof input==='string'?input:(input&&input.url)||'';if(!init||!init.body||!/^\/api\/admin\/rules(?:\/[0-9a-f-]{36})?$/i.test(url))return init;try{var body=JSON.parse(String(init.body));var full=body.name!==undefined||body.settings!==undefined||body.min_commission!==undefined||body.min_discount!==undefined||body.max_price!==undefined||body.sort!==undefined||body.schedule_cron!==undefined;if(!full)return init;body.schedule_cron='0 9-22 * * *';body.settings=Object.assign({},body.settings||{},{intervalMinutes:Number(byId('intervalMinutes')&&byId('intervalMinutes').value)||60,windowStart:(byId('windowStart')&&byId('windowStart').value)||'09:00',windowEnd:(byId('windowEnd')&&byId('windowEnd').value)||'22:00',telegramThreadId:currentThread(),telegramTopicName:currentThread()?currentTopicName():null,listId:(byId('sourceList')&&byId('sourceList').value)||null,listName:(byId('sourceList')&&byId('sourceList').selectedIndex>0?byId('sourceList').options[byId('sourceList').selectedIndex].text.split(' · ')[0]:null)});return Object.assign({},init,{body:JSON.stringify(body)})}catch(e){return init}}
